<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {federationJobsApi as api,type Instance} from '../../infrastructure/federationJobsApi'
const items=ref<Instance[]>([]),page=ref(1),total=ref(0),q=ref(''),busy=ref(false),error=ref('')
async function load(reset=false){if(reset)page.value=1;busy.value=true;error.value='';try{const data=await api.instances(page.value,q.value);items.value=data.items||[];total.value=data.total}catch{error.value='无法读取实例数据，请重试。'}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><div class="admin-page"><header><h1>联邦实例</h1><p>按远端账户与关注关系汇总；最后活动不代表可达性。</p></header><form class="admin-card admin-toolbar" @submit.prevent="load(true)"><label class="admin-field">域名<input v-model="q" maxlength="255" placeholder="example.social" /></label><button class="admin-button" :disabled="busy">查询</button></form><p v-if="error" class="admin-error" role="alert">{{ error }}</p><section class="admin-card" :aria-busy="busy"><p v-if="busy">加载中…</p><p v-else-if="!items.length" class="admin-empty">没有匹配的远端实例。</p><div v-else class="admin-table-wrap"><table class="admin-table"><thead><tr><th>域名</th><th>远端账户</th><th>已停用账户</th><th>本站关注对方</th><th>对方关注本站</th><th>最后记录活动</th></tr></thead><tbody><tr v-for="item in items" :key="item.domain"><td>{{ item.domain }}</td><td>{{ item.accounts }}</td><td>{{ item.suspended_accounts }}</td><td>{{ item.following }}</td><td>{{ item.followers }}</td><td>{{ item.last_activity?new Date(item.last_activity).toLocaleString():'尚无记录' }}</td></tr></tbody></table></div></section><div class="admin-pagination"><button class="admin-button" :disabled="busy||page===1" @click="page--;load()">上一页</button><span>第{{ page }}页，共{{ total }}个实例</span><button class="admin-button" :disabled="busy||page*30>=total" @click="page++;load()">下一页</button></div></div></template>
